#include <bits/stdc++.h>
#define LL long long
#define U unsigned
#define INF 0x7fffffffffffffff
#define MINF (-0x8000000000000000)
bool check_prime(LL x){
    if(x<2) return false;
    for(LL i=2; i<=sqrt(x); i++){
        if(x%i==0) return false;
    }
    return true;
}
inline LL inputLL(){
    LL x=0,f=1; char ch=getchar();
    while (!isdigit(ch)){ if (ch=='-') f=-1; ch=getchar(); }
    while (isdigit(ch)){ x=x*10+ch-48; ch=getchar(); }
    return x*f;
}
LL get_gcd(LL a, LL b){
    return b==0 ? a : get_gcd(b, a%b);
}
LL power_mod(LL base, LL exp, LL mod){
    LL res=1;
    for(; exp; exp>>=1){
        if(exp&1) res=res*base%mod;
        base=base*base%mod;
    }
    return res;
}
using namespace std;
/* Additional code omitted for brevity, same as original */
#define MOD1 998244353LL
#define MOD2 1000000007LL
LL totalN;
LL totalCount;
LL prefixSum[7];
std::vector<LL> prefixDigits[7];

void generate_sequence(LL depth, LL current){
    if(depth>6) return;
    prefixDigits[depth].push_back((totalCount - current + MOD1)%MOD1);
    prefixSum[depth]+=(totalCount - current + MOD1)%MOD1;
    totalCount++;
    for(LL digit=0; digit<=9; digit++){
        generate_sequence(depth+1, current*10+digit);
    }
}

LL counter2=-1, totalAnswer;
void process_sequence(LL depth, LL current){
    if(current>N) return;
    if(current*1000000+999999<=N && current*10000000>N){
        for(LL i=0; i<=6; i++){
            LL shift=(counter2+1 - current*power_mod(10,i,MOD1)%MOD1 + MOD1)%MOD1;
            LL pos=lower_bound(prefixDigits[i].begin(), prefixDigits[i].end(), MOD1-shift) - prefixDigits[i].begin();
            totalAnswer += (prefixSum[i] + shift*prefixDigits[i].size() - MOD1*(prefixDigits[i].size()-pos));
            totalAnswer %= MOD2;
        }
        counter2+=totalCount;
        return;
    }
    counter2++;
    totalAnswer += ((counter2 - current)%MOD1 + MOD1)%MOD1;
    totalAnswer %= MOD2;
    for(LL digit=0; digit<=9; digit++){
        if(!depth && digit==0) continue;
        process_sequence(depth+1, current*10+digit);
    }
}

int main(){
    totalN=inputLL();
    generate_sequence(0,0);
    for(LL i=0; i<=6; i++) sort(prefixDigits[i].begin(), prefixDigits[i].end());
    process_sequence(0,0);
    std::cout<<totalAnswer;
    return 0;
}
